-- Venue Live Guest "Birthday Lego Land". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara legoland), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'legoland', 'Birthday Lego Land (kota balok)', 'legoland', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 123, 'center 38%',
  $t${"name":"Lego Land","orn":"diamond","ui":{"ivory":"#FFF8E1","white":"#FFFFFF","soft":"#FFE9A0","soft2":"#9CC0F5","accent":"#1E5AC8","deep":"#0E2A66","ink":"#14213D","mute":"#5A6A8C","line":"#C9D8F2","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFBEA","ink":"#14213D","accent":"#1E5AC8","gold":"#F5B800","leaf":"#FFE9A0","hbg":"rgba(255,248,225,.94)","hline":"#9CC0F5","motif":"diamond"},"hud":{"bg":"rgba(14,42,102,.86)","acc":"#FFD43B","on":"#14213D"},"scr":{"wine":"#0E2A66","veil":"255,248,225"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'legoland');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/legoland/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/legoland/balloons.webp","w":1.6},"stall_snacks":{"url":"/assets/live-decor/legoland/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/legoland/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/legoland/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/legoland/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/legoland/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/legoland/arch.webp"},"fountain":{"url":"/assets/live-decor/legoland/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/legoland/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/legoland/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/legoland/table.webp"},"banner":{"url":"/assets/live-decor/legoland/banner.webp","w":1.3},"gifts":{"url":"/assets/live-decor/legoland/gifts.webp","w":1.8},"av_host":{"url":"/assets/live-decor/legoland/av_host.webp","name":"Kevin Jaket Merah"},"av_l1":{"url":"/assets/live-decor/legoland/av_l1.webp","name":"Kak Jaket Merah"},"av_l2":{"url":"/assets/live-decor/legoland/av_l2.webp","name":"Kak Kacamata"},"av_l3":{"url":"/assets/live-decor/legoland/av_l3.webp","name":"Kak Topi Biru"},"av_l4":{"url":"/assets/live-decor/legoland/av_l4.webp","name":"Kak Headphone"},"av_p1":{"url":"/assets/live-decor/legoland/av_p1.webp","name":"Kak Hijab Kuning"},"av_p2":{"url":"/assets/live-decor/legoland/av_p2.webp","name":"Kak Pita Merah"},"av_p3":{"url":"/assets/live-decor/legoland/av_p3.webp","name":"Kak Hijab Merah"}}$d$::jsonb, background_url = '/assets/live-decor/legoland/painting.webp', active = true, updated_at = now() where key = 'legoland';
